<?php
require __DIR__.'/includes/bootstrap.php';
$slug=trim($_GET['slug']??'');$subcategory=trim($_GET['subcategory']??'');$page=max(1,(int)($_GET['page']??1));$perPage=12;$category=null;$rows=[];$subcategories=[];$total=0;
if($pdo&&$slug!==''){$s=$pdo->prepare('SELECT * FROM categories WHERE slug=? LIMIT 1');$s->execute([$slug]);$category=$s->fetch();}
if(!$category){http_response_code(404);$title='Category not found';$description='The requested category is unavailable.';}else{$title=$category['name'];$description=$category['description']?:('Guides and resources about '.strtolower($title).'.');$where="status='published' AND category=?";$params=[$category['name']];if($subcategory!==''){$where.=' AND subcategory=?';$params[]=$subcategory;}$count=$pdo->prepare("SELECT COUNT(*) FROM articles WHERE $where");$count->execute($params);$total=(int)$count->fetchColumn();$query="SELECT * FROM articles WHERE $where ORDER BY featured DESC,published_at DESC LIMIT $perPage OFFSET ".(($page-1)*$perPage);$s=$pdo->prepare($query);$s->execute($params);$rows=$s->fetchAll();$s=$pdo->prepare("SELECT DISTINCT subcategory FROM articles WHERE status='published' AND category=? AND subcategory IS NOT NULL AND subcategory<>'' ORDER BY subcategory");$s->execute([$category['name']]);$subcategories=$s->fetchAll(PDO::FETCH_COLUMN);$canonical=url($slug.'/'.($subcategory!==''?'?subcategory='.rawurlencode($subcategory):''));$list=[];foreach($rows as $row)$list[]=['name'=>$row['title'],'url'=>url($slug.'/'.$row['slug'].'/')];$schema=item_list_schema($list);$extra_schema=breadcrumb_schema(['Home'=>url(),$category['name']=>$canonical]);}
$pages=(int)ceil($total/$perPage);$prev_url=$page>1?url($slug.'/?page='.($page-1)):null;$next_url=$page<$pages?url($slug.'/?page='.($page+1)):null;require __DIR__.'/includes/header.php';
?><div class="container"><p class="muted"><a href="<?=url()?>">Home</a> / <?=e($title)?></p><h1><?=e($title)?></h1><p><?=e($description)?></p><?php if($subcategories):?><nav class="card" aria-label="Subcategories"><a href="<?=url($slug.'/')?>">All</a><?php foreach($subcategories as $sub):?> &middot; <a href="<?=url($slug.'/?subcategory='.rawurlencode($sub))?>"><?=e($sub)?></a><?php endforeach;?></nav><?php endif;?><p class="muted"><?=e((string)$total)?> published article(s).</p><div class="grid"><?php foreach($rows as $article):?><article class="card"><?php if(!empty($article['featured_image'])):?><img loading="lazy" src="<?=url('uploads/'.$article['featured_image'])?>" alt="<?=e($article['title'])?>"><?php endif;?><p class="eyebrow"><?=e($article['subcategory']?:$category['name'])?></p><h2><a href="<?=url($slug.'/'.$article['slug'].'/')?>"><?=e($article['title'])?></a></h2><p><?=e($article['excerpt'])?></p></article><?php endforeach;?></div><?php if($category&&!$rows):?><p>No published articles found. Try another subcategory.</p><?php endif;?><?php $pages=(int)ceil($total/$perPage);if($pages>1):?><nav aria-label="Category pagination"><?php for($i=1;$i<=$pages;$i++):?><a <?=$i===$page?'aria-current="page"':''?> href="?slug=<?=rawurlencode($slug)?>&subcategory=<?=rawurlencode($subcategory)?>&page=<?=$i?>"><?=$i?></a> <?php endfor;?></nav><?php endif;?></div><?php require __DIR__.'/includes/footer.php';
